const table = {};
function put(op, tag, fn) { table[op + '/' + tag] = fn; }
function get(op, tag) { return table[op + '/' + tag]; }

put('add', 'ordinary', (a, b) => a.value + b.value);
put('add', 'rational', (a, b) => ({ n: a.n * b.d + b.n * a.d, d: a.d * b.d }));

function genericAdd(tag, a, b) { return get('add', tag)(a, b); }

console.log(genericAdd('ordinary', { value: 3 }, { value: 4 }));
console.log(genericAdd('rational', { n: 1, d: 2 }, { n: 1, d: 3 }));

