const table = {};
function put(op, tags, fn) { table[op + '/' + tags] = fn; }
function get(op, tags) { return table[op + '/' + tags]; }

put('add', 'rational,rational', (a, b) => ({ n: a.n * b.d + b.n * a.d, d: a.d * b.d }));

function toRational(n) { return { n, d: 1 }; }

function genericAdd(aTag, a, bTag, b) {
  const direct = get('add', aTag + ',' + bTag);
  if (direct) return direct(a, b);
  if (aTag === 'ordinary' && bTag === 'rational') {
    return get('add', 'rational,rational')(toRational(a), b);
  }
  throw new Error('no implementation');
}

console.log(genericAdd('ordinary', 3, 'rational', { n: 1, d: 2 }));

